import{_ as l,a0 as p,w as d,s as o,ao as r,I as n,x as s,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 命令列中轉換大小寫 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 命令列中轉換大小寫 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 命令列中轉換大小寫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 命令列中轉換大小寫 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200228 Converting between uppercase and lowercase on the Linux command line","title":"在 Linux 命令列中轉換大小寫","tag":"202003","desc":""},"relativePath":"202003/20200228 Converting between uppercase and lowercase on the Linux command line.md","filePath":"[post].md"}'),h={name:"202003/20200228 Converting between uppercase and lowercase on the Linux command line.md"};function c(g,e,k,u,b,m){const a=p("Link");return d(),o("div",null,[e[15]||(e[15]=r(`<h1 id="在-linux-命令列中轉換大小寫" tabindex="-1">在 Linux 命令列中轉換大小寫 <a class="header-anchor" href="#在-linux-命令列中轉換大小寫" aria-label="Permalink to “在 Linux 命令列中轉換大小寫”">​</a></h1><blockquote><p>轉換文本的大小寫可能非常繁瑣，尤其是當你要避免無意間的拼寫錯誤時。幸運的是，Linux 提供了一些命令，可以使工作變得非常容易。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/11/095821df7u8nlyfyyydqvf.jpg" alt=""></p><p>有很多方法可以在 Linux 命令列中將文本從小寫更改為大寫，反之亦然。實際上，有一組這樣的命令可以選擇。這篇文章檢驗了一些最佳的命令來完成這項工作，以及你該如何讓它們正常工作。</p><h3 id="使用-tr" tabindex="-1">使用 tr <a class="header-anchor" href="#使用-tr" aria-label="Permalink to “使用 tr”">​</a></h3><p><code>tr</code>（translate）命令是在命令列或腳本中最容易使用的命令之一。如果你要確定要一串大寫字符串，你只需將它傳給 <code>tr</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo Hello There | tr [:lower:] [:upper:]</span></span>
<span class="line"><span>HELLO THERE</span></span></code></pre></div><p>下面是一個在腳本中使用這個命令的例子，當你要確保添加到文件中的所有文本都使用大寫形式以保持一致性時（LCTT 譯註：這裏輸入部門名稱作為示例）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo -n &quot;Enter department name: &quot;</span></span>
<span class="line"><span>read dept</span></span>
<span class="line"><span>echo $dept | tr [:lower:] [:upper:] &gt;&gt; depts</span></span></code></pre></div><p>將順序切換為 <code>[:upper:] [:lower:]</code> 會產生相反的效果，將所有大寫的部門名稱都轉換為小寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | tr [:upper:] [:lower:] &gt;&gt; depts</span></span></code></pre></div><p>同樣，你可以使用 <code>sed</code> 命令的 <code>A-Z</code> 和 <code>a-z</code> 字符串完成相同的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | tr a-z A-Z &gt;&gt; depts</span></span></code></pre></div><p>毫無疑問，反轉 <code>a-z</code> 和 <code>A-Z</code> 字符串的順序將產生相反的效果，將文本全部變為小寫。</p><h3 id="使用-awk" tabindex="-1">使用 awk <a class="header-anchor" href="#使用-awk" aria-label="Permalink to “使用 awk”">​</a></h3><p><code>awk</code> 命令可讓你使用它的 <code>toupper</code> 和 <code>tolower</code> 選項執行相同的操作。上例腳本中的命令可以用這種方式代替：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | awk &#39;{print toupper($0)}&#39; &gt;&gt; depts</span></span></code></pre></div><p>相反操作（切換為小寫）如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | awk &#39;{print tolower($0)}&#39; &gt;&gt; depts</span></span></code></pre></div><h3 id="使用-sed" tabindex="-1">使用 sed <a class="header-anchor" href="#使用-sed" aria-label="Permalink to “使用 sed”">​</a></h3><p><code>sed</code>（stream editor）命令也可用於切換大小寫。它與上面顯示的兩個命令中的第一個具有相同的效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | sed &#39;s/[a-z]/\\U&amp;/g&#39; &gt;&gt; depts</span></span></code></pre></div><p>從大寫字母切換到小寫字母只需將行尾附近的 <code>U</code> 替換為 <code>L</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $dept | sed &#39;s/[A-Z]/\\L&amp;/g&#39; &gt;&gt; depts</span></span></code></pre></div><h3 id="操作文件中的文本" tabindex="-1">操作文件中的文本 <a class="header-anchor" href="#操作文件中的文本" aria-label="Permalink to “操作文件中的文本”">​</a></h3><p><code>awk</code> 和 <code>sed</code> 都能更改整個文件的文本大小寫。因此，你發現你的老闆需要所有部門名稱的小寫麼？沒問題。只需帶上文件名運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;{print tolower($0)}&#39; depts</span></span>
<span class="line"><span>finance</span></span>
<span class="line"><span>billing</span></span>
<span class="line"><span>bookkeeping</span></span></code></pre></div><p>如果要覆蓋 <code>depts</code> 文件，而不僅僅是以小寫形式顯示，則需要執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;{print tolower($0)}&#39; depts &gt; depts-</span></span>
<span class="line"><span>$ mv depts- depts</span></span></code></pre></div><p>但是，使用 <code>sed</code> 進行更改，你可以避免最後一步，因為 <code>sed</code> 可以“原地”編輯文件，如下所示，文件完整，但文本全部小寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed &#39;s/[A-Z]/\\L&amp;/g&#39; depts</span></span></code></pre></div><h3 id="僅將首字母轉換為大寫" tabindex="-1">僅將首字母轉換為大寫 <a class="header-anchor" href="#僅將首字母轉換為大寫" aria-label="Permalink to “僅將首字母轉換為大寫”">​</a></h3><p>要僅將字符串中單詞的首字母轉換為大寫，那麼可以執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo design \\&amp; engineering| sed -e &quot;s/\\b\\(.\\)/\\u\\1/g&quot;</span></span>
<span class="line"><span>Design &amp; Engineering</span></span></code></pre></div><p>該命令將確保首字母大寫，但不會更改其餘字母。</p><h3 id="確保只有首字母大寫" tabindex="-1">確保只有首字母大寫 <a class="header-anchor" href="#確保只有首字母大寫" aria-label="Permalink to “確保只有首字母大寫”">​</a></h3><p>當要更改文本以使只有首字母大寫時，這更具挑戰性。假設你正在處理一個工作人員姓名列表，並且希望以正常的“名 姓”方式對其格式化。</p><h4 id="使用-sed-1" tabindex="-1">使用 sed <a class="header-anchor" href="#使用-sed-1" aria-label="Permalink to “使用 sed”">​</a></h4><p>你可以使用更復雜的 <code>sed</code> 命令來確保以下結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo design \\&amp; ENGINEERING | sed &#39;s/\\b\\([[:alpha:]]\\)\\([[:alpha:]]*\\)\\b/\\u\\1\\L\\2/g&#39;</span></span>
<span class="line"><span>Design &amp; Engineering</span></span></code></pre></div><h4 id="使用-python" tabindex="-1">使用 Python <a class="header-anchor" href="#使用-python" aria-label="Permalink to “使用 Python”">​</a></h4><p>如果你已安裝 Python，你可以運行這樣的命令，它還可以設置文本格式，以便每個單詞只有首字母大寫，並且它可能比上面顯示的 <code>sed</code> 命令更易於解析：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo -n &quot;design &amp; engineering&quot; | python3 -c &quot;import sys; print(sys.stdin.read().title())&quot;</span></span>
<span class="line"><span>Design &amp; Engineering</span></span></code></pre></div><p>有多種方法可以在大小寫之間更改文本格式。哪種方法效果最好取決於你要處理的是單個字符串還是整個文件，以及想要的最終結果。</p><hr>`,45)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://www.networkworld.com/article/3529409/converting-between-uppercase-and-lowercase-on-the-linux-command-line.html"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3529409/converting-between-uppercase-and-lowercase-on-the-linux-command-line.html",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),i(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:t(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const w=l(h,[["render",c]]);export{x as __pageData,w as default};
